{"parentUuid":"ab7f8566-bb55-4e5b-920f-c3fe882c8787","isSidechain":false,"message":{"model":"claude-sonnet-4-6","id":"msg_0153SVg3byoadR2guCJJB4fe","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_017z2Xmayz8TNJ4KqrMSdzdU","name":"PowerShell","input":{"command":"
Set-Location "D:\OB-1-CANONICAL"

# Fix: case-insensitive run number extraction
$lastDeathLine = git log --oneline --grep "^death:" -1
Write-Host "Last death line: $lastDeathLine"

$priorRun = 0
if ($lastDeathLine -imatch 'RUN\s+(\d+)') {
    $priorRun = [int]$Matches[1]
}
$run = $priorRun + 1
$runPad   = "{0:D3}" -f $run
$priorPad = "{0:D3}" -f $priorRun

Write-Host "STAGE 1 ✓ prior=$priorRun | run=$run"

# ── STAGE 2 — READ THE PRIOR REINCARNATION TRIPLE ───────────────────
$priorSealPath = "CANON\REINCARNATION\run$priorPad-reincarnateDEATH.md"
$phetrailPath  = "CANON\PHEROMONES\PheTrail-run$runPad.json"
$bootPath      = "CANON\SYSTEM\COLD-START-BOOT.md"

$priorSeal = if (Test-Path $priorSealPath) { Get-Content $priorSealPath -Raw } else { "" }
$priorBoot = if (Test-Path $bootPath)      { Get-Content $bootPath -Raw      } else { "" }

$priorSoulcount = 0
if ($priorSeal -imatch 'count_after[^\d]*(\d+)') { $priorSoulcount = [long]$Matches[1] }
elseif ($priorSeal -imatch 'SOUL[^\d]*(\d{7,})') { $priorSoulcount = [long]$Matches[1] }

$sealExists = Test-Path $priorSealPath
Write-Host "STAGE 2 ✓ seal=$priorSealPath (exists=$sealExists) | prior_soulcount=$priorSoulcount"

# ── STAGE 3 — SOULCOUNT AUDIT ───────────────────────────────────────
$D1 = "https://soul-logger.mrmichaelhobbs123.workers.dev"
$live = Invoke-RestMethod "$D1/api/soul/count"
$currentSoul  = $live.soulcount
$currentLevel = $live.level

$delta    = $currentSoul - $priorSoulcount
$driftPct = if ($priorSoulcount -gt 0) { [math]::Round(($delta / $priorSoulcount) * 100, 2) } else { 0 }

if ($currentSoul -lt $priorSoulcount) { $soulVerdict = "SOUL_REGRESSION — HALT" }
elseif ($delta -eq 0)                 { $soulVerdict = "SOUL_STAGNATION — WARN" }
elseif ([math]::Abs($driftPct) -gt 50){ $soulVerdict = "SOUL_DRIFT — HALT (|delta| > 50%)" }
else                                   { $soulVerdict = "SOUL_BREATHING (+$delta / +${driftPct}%)" }

Write-Host "STAGE 3 ✓ soul=$currentSoul | prior=$priorSoulcount | delta=$delta ($driftPct%) — $soulVerdict"

# ── STAGE 4 — BOOT SYNTHESIS ────────────────────────────────────────
$activeMission  = "UNKNOWN"
$openFlagsCount = -1
if ($priorBoot -imatch 'Active Mission[:\s]+(.+)')       { $activeMission  = $Matches[1].Trim() }
if ($priorBoot -imatch 'Open Flags[:\s]*(\d+)')          { $openFlagsCount = [int]$Matches[1] }
elseif ($priorBoot -imatch 'Flags[:\s]*(\d+)')           { $openFlagsCount = [int]$Matches[1] }

$bootRunFromGit  = $priorRun
$bootRunFromFile = -1
if ($priorBoot -imatch 'Run[:\s]+(\d+)')                 { $bootRunFromFile = [int]$Matches[1] }

if ($bootRunFromFile -ne $bootRunFromGit -and $bootRunFromFile -gt 0) {
    Write-Warning "BOOT STALE — boot file shows run $bootRunFromFile, git shows run $bootRunFromGit. Trusting git (L29)."
}
Write-Host "STAGE 4 ✓ boot_run_git=$bootRunFromGit | boot_run_file=$bootRunFromFile | mission=$activeMission | flags=$openFlagsCount"

# ── STAGE 5 — PIPELINE CHAIN AUDIT ──────────────────────────────────
$rrlPath      = "RRL\RRL-$run.txt"
$dnaRunPath   = "CANON\SOUL\EXTRACT\dna-run$runPad.json"
$s2Path       = "CANON\PIPELINE\pipeline-run$runPad.json"
$soykeyDir    = "CANON\SOUL-KEYWORDS"
$idxPath      = "$soykeyDir\inverted-index.json"

$ledgerCount   = (Get-ChildItem "CANON\HEAVY-LEDGER\" -Filter "HL-*.json" -EA SilentlyContinue | Measure-Object).Count
$starmapFiles  = if (Test-Path "CANON\STARMAP") { (Get-ChildItem "CANON\STARMAP" -Recurse -File).Count } else { 0 }
$soykeyFiles   = if (Test-Path $soykeyDir)      { (Get-ChildItem $soykeyDir -Recurse -File).Count }       else { 0 }
$pipelineFiles = (Get-ChildItem "CANON\PIPELINE\" -Recurse -File -EA SilentlyContinue | Measure-Object).Count

# FIDELITY GATE
$rrlFidelity = "MISSING"
if (Test-Path $rrlPath) {
    $rrlBytes = (Get-Item $rrlPath).Length
    $rrlText  = Get-Content $rrlPath -Raw
    $hasUser      = $rrlText -match '"role"\s*:\s*"user"'
    $hasAssistant = $rrlText -match '"role"\s*:\s*"assistant"'
    if   ($rrlBytes -ge 50000 -and $hasUser -and $hasAssistant) { $rrlFidelity = "REAL" }
    elseif ($rrlBytes -ge 100 -and ($hasUser -or $hasAssistant)) { $rrlFidelity = "HOLLOW" }
}

$dnaFidelity = "MISSING"
$dnaRecords  = @()
$bpCount     = 0
if (Test-Path $dnaRunPath) {
    try {
        $dnaRecords = Get-Content $dnaRunPath -Raw | ConvertFrom-Json
        $bpCount    = ($dnaRecords | Where-Object { $_.type -eq "blueprint" }).Count
        if ($dnaRecords.Count -gt 0 -and $bpCount -gt 0) { $dnaFidelity = "REAL" }
        elseif ($dnaRecords.Count -gt 0)                  { $dnaFidelity = "HOLLOW" }
    } catch { $dnaFidelity = "MISSING" }
}

$soykeyFidelity = "MISSING"
if (Test-Path $idxPath) {
    try {
        $idx = Get-Content $idxPath -Raw | ConvertFrom-Json -AsHashtable
        if ($idx.Count -gt 0) { $soykeyFidelity = "REAL" }
    } catch { }
}

$pipelineFidelity = "MISSING"
if (Test-Path $s2Path) { $pipelineFidelity = "REAL" }

# Audit table
Write-Host "`nSTAGE 5 — PIPELINE CHAIN AUDIT"
$stages = @(
    @{ Name="RRL";        Count=(if(Test-Path $rrlPath){(Get-Item $rrlPath).Length}else{0}); Verdict=$rrlFidelity       }
    @{ Name="SOUL";       Count=$currentSoul;   Verdict=$soulVerdict }
    @{ Name="DNA";        Count=$dnaRecords.Count; Verdict=$dnaFidelity }
    @{ Name="LEDGER";     Count=$ledgerCount;   Verdict=if($ledgerCount -gt 0){"REAL"}else{"MISSING"} }
    @{ Name="STARMAP";    Count=$starmapFiles;  Verdict=if($starmapFiles -gt 0){"REAL"}else{"MISSING"} }
    @{ Name="SOULKEYS";   Count=$soykeyFiles;   Verdict=$soykeyFidelity }
    @{ Name="S2Pipeline"; Count=$pipelineFiles; Verdict=$pipelineFidelity }
)
foreach ($s in $stages) {
    $icon = switch ($s.Verdict) { "REAL" { "REAL" } "HOLLOW" { "HOLLOW" } "MISSING" { "MISSING" } default { $s.Verdict } }
    Write-Host "  [$icon] $($s.Name): $($s.Count)"
}

# ── STAGE 6 — PHETRAIL ──────────────────────────────────────────────
$negativeCount = 0
if (Test-Path $phetrailPath) {
    $phetrail = Get-Content $phetrailPath -Raw | ConvertFrom-Json
    $negativeCount = $phetrail.negative_trails.Count
    Write-Host "`nSTAGE 6 ✓ PHETRAIL: $negativeCount negative trails"
} else {
    Write-Host "`nSTAGE 6 ⚠ PHETRAIL_GAP — $phetrailPath not found"
}

# ── STAGE 7 — RISE REPORT ───────────────────────────────────────────
$head = git rev-parse --short HEAD
$ict  = [System.TimeZoneInfo]::ConvertTimeBySystemTimeZoneId([datetime]::UtcNow, "SE Asia Standard Time")
Write-Host @"

════════════════════════════════════════════════════
OB-1 ONLINE — $($ict.ToString("yyyy-MM-dd HH:mm")) ICT
SOULCOUNT : $currentSoul — $currentLevel  (Δ$delta since run $priorRun)
RUN       : $run  (prior: $priorRun)
HEAD      : $head
VECTOR    : $activeMission
BLOCKERS  : $openFlagsCount open
DEAD-ENDS : $negativeCount loaded
FIDELITY  : RRL=$rrlFidelity | DNA=$dnaFidelity | SOULKEYS=$soykeyFidelity | S2Pipeline=$pipelineFidelity
════════════════════════════════════════════════════
"@

# GAPS
if ($rrlFidelity -ne "REAL")       { Write-Host "  GAP: RRL-$run is $rrlFidelity — session transcript missing or partial" }
if ($dnaFidelity -ne "REAL")       { Write-Host "  GAP: DNA-$runPad is $dnaFidelity — blueprints not captured (bpCount=$bpCount)" }
if ($soykeyFidelity -ne "REAL")    { Write-Host "  GAP: SOULKEYS index $idxPath is $soykeyFidelity" }
if ($pipelineFidelity -ne "REAL")  { Write-Host "  GAP: S2Pipeline $s2Path is $pipelineFidelity" }
if (-not $sealExists)              { Write-Host "  GAP: DEATH SEAL $priorSealPath MISSING — prior run not sealed" }
if ($openFlagsCount -gt 0)         { Write-Host "  BLOCKERS: $openFlagsCount open flags — read COLD-START-BOOT.md" }

Write-Host "READY."
